                'action_statement' => 'BEGIN
  DECLARE matching_revision_count bigint unsigned DEFAULT 0;
  IF OLD.`supplier_product_identity_head_id` IS NOT NULL
     AND NOT (OLD.`supplier_product_identity_head_id` <=> NEW.`supplier_product_identity_head_id`) THEN
    SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT = \'Supplier product identity head is immutable\';
  END IF;
  IF (NEW.`supplier_product_identity_head_id` IS NULL) <> (NEW.`current_source_revision_id` IS NULL) THEN
    SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT = \'Supplier product source pointers must be complete\';
  END IF;
  IF NOT (OLD.`current_source_revision_id` <=> NEW.`current_source_revision_id`) THEN
    IF NEW.`current_source_revision_id` IS NULL THEN
      SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT = \'Supplier product source revision cannot be cleared\';
    END IF;
    SELECT COUNT(*) INTO matching_revision_count
      FROM `supplier_product_source_revisions`
      WHERE `id` = NEW.`current_source_revision_id`
        AND `supplier_product_id` = NEW.`id`
        AND `supplier_product_identity_head_id` = NEW.`supplier_product_identity_head_id`
        AND `supplier_id` = NEW.`supplier_id`
        AND `supplier_feed_id` = NEW.`supplier_feed_id`;
    IF matching_revision_count <> 1 THEN
      SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT = \'Supplier product source revision scope mismatch\';
    END IF;
  ELSEIF NOT (OLD.`supplier_sku` <=> NEW.`supplier_sku`)
      OR NOT (OLD.`ean` <=> NEW.`ean`)
      OR NOT (OLD.`mpn` <=> NEW.`mpn`)
      OR NOT (OLD.`name` <=> NEW.`name`)
      OR NOT (OLD.`brand_name` <=> NEW.`brand_name`)
      OR NOT (OLD.`category_name` <=> NEW.`category_name`)
      OR NOT (OLD.`price` <=> NEW.`price`)
