      OR NOT (OLD.`recommended_price` <=> NEW.`recommended_price`)
      OR NOT (OLD.`quantity` <=> NEW.`quantity`)
      OR NOT (OLD.`external_availability_status` <=> NEW.`external_availability_status`)
      OR NOT (OLD.`external_availability_label` <=> NEW.`external_availability_label`)
      OR NOT (OLD.`availability_status_id` <=> NEW.`availability_status_id`)
      OR NOT (OLD.`currency` <=> NEW.`currency`)
