      OR NOT (OLD.`payload_hash` <=> NEW.`payload_hash`)
      OR NOT (OLD.`received_at` <=> NEW.`received_at`) THEN
    SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT = \'Source-owned projection change requires revision pointer CAS\';
  END IF;
END',
