    /** @return list<array<string, mixed>> */
    public static function signatures(): array
    {
        return self::EXPECTED_SIGNATURES;
    }

    /** @return list<array<string, mixed>> */
    public static function states(): array
    {
        return self::EXPECTED_STATES;
    }

    /** @return list<array<string, mixed>> */
    public static function operations(): array
    {
        return self::EXPECTED_OPERATIONS;
    }

    /** @return array<string, array<string, mixed>> */
    public static function signaturesFor(string $state): array
    {
        $signatures = [];

        foreach (self::EXPECTED_SIGNATURES as $record) {
            if (in_array($state, $record['memberships'], true)) {
                $signatures[$record['object_id']] = $record;
            }
        }

        ksort($signatures, SORT_STRING);

        return $signatures;
    }

    /** @return array<string, mixed> */
    public static function state(string $state): array
    {
        foreach (self::EXPECTED_STATES as $record) {
            if ($record['state'] === $state) {
                return $record;
            }
        }

        throw new RuntimeException('unknown_phase_three_p0_oracle_state');
    }

    /** @return array<string, mixed> */
    public static function operation(string $operationId): array
    {
        foreach (self::EXPECTED_OPERATIONS as $record) {
            if ($record['operation_id'] === $operationId) {
                return $record;
            }
        }

        throw new RuntimeException('unknown_phase_three_p0_oracle_operation');
    }

    public static function metadataBytes(): string
    {
        try {
            return json_encode([
                'version' => self::METADATA_VERSION,
                'objects' => array_map(static fn (array $record): array => [
                    'registry_id' => $record['registry_id'],
                    'object_id' => $record['object_id'],
                    'owner' => $record['owner'],
                    'memberships' => $record['memberships'],
                ], self::EXPECTED_SIGNATURES),
                'states' => array_map(static fn (array $record): array => [
                    'state' => $record['state'],
                    'classification' => $record['classification'],
                    'domain' => $record['domain'],
                    'object_counts' => $record['object_counts'],
                    'object_count' => $record['object_count'],
                    'sha256' => $record['sha256'],
                ], self::EXPECTED_STATES),
                'operations' => array_map(static fn (array $record): array => [
                    'operation_id' => $record['operation_id'],
                    'precondition_state' => $record['precondition_state'],
                    'precondition_sha256' => $record['precondition_sha256'],
                    'responsibility' => $record['responsibility'],
                    'statement_atomicity' => $record['statement_atomicity'],
                    'affected_objects' => $record['affected_objects'],
                    'result_state' => $record['result_state'],
                    'result_sha256' => $record['result_sha256'],
                    'next_operation' => $record['next_operation'],
                ], self::EXPECTED_OPERATIONS),
            ], JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        } catch (JsonException $exception) {
            throw new RuntimeException('phase_three_p0_oracle_metadata_encoding_failed', previous: $exception);
        }
    }

    public static function assertIntegrity(): void
    {
        $bytes = self::metadataBytes();

        if (count(self::EXPECTED_SIGNATURES) !== 375
            || count(self::EXPECTED_STATES) !== 17
            || count(self::EXPECTED_OPERATIONS) !== 15
            || strlen($bytes) !== self::METADATA_BYTES
            || hash('sha256', self::METADATA_VERSION."\0".$bytes) !== self::METADATA_SHA256) {
            throw new RuntimeException('phase_three_p0_oracle_integrity_failed');
        }
    }
